import { Component, createMemo } from "solid-js";

import { Icon } from "#core/ui-next/components/icon.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";

export interface AttributeIconProps {
	attribute?: string;
	class?: string;
}

export const AttributeIcon: Component<AttributeIconProps> = (props) => {
	const iconName = createMemo(
		() => props.attribute?.replace("LOC_TAG_TRAIT_", "ATTRIBUTE_").replace("_NAME", "") ?? "",
	);

	return (
		<Tooltip.Text
			bodyClass="flex flex-row justify-center"
			text={props.attribute ?? ""}
		>
			<Icon
				name={iconName()}
				class={`relative ${props.class ?? ""}`}
				context="OUTLINE"
			/>
		</Tooltip.Text>
	);
};
